-- =====================================================================
-- BREWPASTORE - "La birra del giorno": 500 frasi a rotazione giornaliera
-- Generato da supabase/seed/quotes_*.txt
-- =====================================================================

create table public.beer_quotes (
  id       int primary key,
  category text not null check (category in ('curiosita','storia','consiglio','proverbio','battuta','citazione')),
  text     text not null,
  author   text,
  active   boolean not null default true
);

alter table public.beer_quotes enable row level security;
create policy "quotes_read"  on public.beer_quotes for select to authenticated using (true);
create policy "quotes_admin" on public.beer_quotes for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Frase del giorno: uguale per tutti nello stesso giorno (fuso orario italiano).
-- L'ordine è un mescolamento fisso pseudo-casuale: nessuna ripetizione finché non sono uscite tutte.
create or replace function public.quote_of_the_day()
returns setof public.beer_quotes
language sql stable as $$
  with ordered as (
    select q.*, row_number() over (order by md5(q.id::text || 'brewpastore')) - 1 as pos,
           count(*) over () as n
    from public.beer_quotes q where q.active
  )
  select id, category, text, author, active from ordered
  where pos = ((now() at time zone 'Europe/Rome')::date - date '2026-01-01') % n
$$;

create or replace function public.random_quote()
returns setof public.beer_quotes
language sql volatile as $$
  select * from public.beer_quotes where active order by random() limit 1
$$;

