insert into public.beer_quotes (id, category, text, author) values
  (1, 'curiosita', 'La birra è composta per oltre il 90% da acqua: per questo il profilo dell''acqua di una città ha plasmato interi stili.', null),
  (2, 'curiosita', 'L''acqua di Pilsen è molto dolce, povera di sali: è uno dei segreti della morbidezza della Pilsner originale.', null),
  (3, 'curiosita', 'L''acqua di Burton-on-Trent è ricchissima di solfato di calcio: da qui il termine "burtonizzare" l''acqua per le pale ale.', null),
  (4, 'curiosita', 'La prima Pilsner fu prodotta nel 1842 a Plzeň dal birraio bavarese Josef Groll.', null),
  (5, 'curiosita', 'Il luppolo è un parente stretto della cannabis: entrambi appartengono alla famiglia delle Cannabaceae.', null),
  (6, 'curiosita', 'Il luppolo è una pianta rampicante che può crescere fino a circa 30 cm in un solo giorno nel pieno della stagione.', null),
  (7, 'curiosita', 'Si usano solo i coni delle piante femminili di luppolo: è lì che si trovano le ghiandole di luppolina.', null),
  (8, 'curiosita', 'La luppolina, la polverina gialla nei coni, contiene alfa acidi, beta acidi e oli essenziali.', null),
  (9, 'curiosita', 'Gli alfa acidi del luppolo diventano amari solo dopo l''isomerizzazione durante la bollitura.', null),
  (10, 'curiosita', 'Gli IBU (International Bitterness Units) misurano i milligrammi di iso-alfa acidi per litro di birra.', null),
  (11, 'curiosita', 'Oltre i 100 IBU circa il palato umano fatica a percepire differenze di amaro.', null),
  (12, 'curiosita', 'Il luppolo ha proprietà antibatteriche: è uno dei motivi per cui venne adottato per conservare la birra.', null),
  (13, 'curiosita', 'Prima del luppolo, la birra veniva aromatizzata con il gruit, una miscela di erbe come mirto di palude, achillea e rosmarino selvatico.', null),
  (14, 'curiosita', 'Il lievito Saccharomyces cerevisiae è lo stesso organismo usato per fare il pane.', null),
  (15, 'curiosita', 'Il lievito lager Saccharomyces pastorianus è un ibrido naturale tra S. cerevisiae e S. eubayanus.', null),
  (16, 'curiosita', 'S. eubayanus, uno dei "genitori" del lievito lager, è stato identificato in Patagonia solo nel 2011.', null),
  (17, 'curiosita', 'Louis Pasteur pubblicò nel 1876 gli "Études sur la bière", studi sulla fermentazione della birra.', null),
  (18, 'curiosita', 'Emil Christian Hansen, al laboratorio Carlsberg, isolò per primo una coltura pura di lievito lager negli anni 1880.', null),
  (19, 'curiosita', 'La scala del pH fu introdotta nel 1909 da Søren Sørensen, chimico del Laboratorio Carlsberg.', null),
  (20, 'curiosita', 'Il pH ideale del mash per la maggior parte delle birre si colloca tra 5,2 e 5,6 (misurato a temperatura ambiente).', null),
  (21, 'curiosita', 'Gli enzimi beta-amilasi lavorano meglio intorno ai 60–65 °C e producono zuccheri fermentabili.', null),
  (22, 'curiosita', 'Gli enzimi alfa-amilasi preferiscono 68–72 °C e producono zuccheri più complessi: più corpo, meno fermentabilità.', null),
  (23, 'curiosita', 'Una birra con mash a 64 °C sarà in genere più secca di una con mash a 69 °C.', null),
  (24, 'curiosita', 'Il maltosio è lo zucchero più abbondante in un mosto tipico.', null),
  (25, 'curiosita', 'La maltazione consiste nel far germinare l''orzo e poi bloccare la germinazione con il calore.', null),
  (26, 'curiosita', 'I malti scuri come il black malt vengono tostati fino a oltre 200 °C.', null),
  (27, 'curiosita', 'Il colore della birra si misura in EBC in Europa e in SRM negli Stati Uniti: EBC ≈ SRM × 1,97.', null),
  (28, 'curiosita', 'Un''equazione popolare per stimare l''ABV è (OG − FG) × 131,25.', null),
  (29, 'curiosita', 'La densità dell''acqua pura a 20 °C è il riferimento 1,000 per i densimetri da birra.', null),
  (30, 'curiosita', 'Un grado Plato corrisponde circa a 4 "punti" di densità: 12 °P ≈ 1,048.', null),
  (31, 'curiosita', 'L''alcol è meno denso dell''acqua: per questo la densità scende durante la fermentazione.', null),
  (32, 'curiosita', 'Il rifrattometro va corretto quando c''è alcol nel campione: le letture dopo la fermentazione sono falsate.', null),
  (33, 'curiosita', 'Il diacetile dà un aroma di burro o caramella mou: il "riposo del diacetile" aiuta il lievito a riassorbirlo.', null),
  (34, 'curiosita', 'Il DMS (dimetilsolfuro) ricorda il mais cotto: una bollitura vigorosa e scoperta aiuta a eliminarlo.', null),
  (35, 'curiosita', 'L''acetaldeide sa di mela verde ed è spesso segno di una birra "giovane".', null),
  (36, 'curiosita', 'I fenoli tipici delle weizen (chiodo di garofano) vengono dal gene POF+ di certi lieviti.', null),
  (37, 'curiosita', 'Il banana delle weizen è dovuto all''isoamil acetato, un estere prodotto dal lievito.', null),
  (38, 'curiosita', 'Fermentare più caldo in genere aumenta la produzione di esteri fruttati.', null),
  (39, 'curiosita', 'Il "lightstruck" o "skunky" è causato dalla luce che degrada i composti del luppolo: per questo le bottiglie scure proteggono meglio.', null),
  (40, 'curiosita', 'Le bottiglie marroni filtrano molta più luce dannosa rispetto a quelle verdi o trasparenti.', null),
  (41, 'curiosita', 'L''ossigeno è il nemico della birra finita: l''ossidazione dà note di cartone bagnato.', null),
  (42, 'curiosita', 'L''ossigeno è invece amico del lievito all''inizio: va dato al mosto freddo prima dell''inoculo.', null),
  (43, 'curiosita', 'Il "cold break" è la precipitazione di proteine quando il mosto viene raffreddato rapidamente.', null),
  (44, 'curiosita', 'Il "hot break" è la schiuma proteica che si forma all''inizio della bollitura.', null),
  (45, 'curiosita', 'Il whirlpool crea un cono di trub al centro della pentola, facilitando il travaso del mosto limpido.', null),
  (46, 'curiosita', 'L''Irish moss è un''alga (Chondrus crispus) usata come chiarificante negli ultimi minuti di bollitura.', null),
  (47, 'curiosita', 'La colla di pesce (isinglass) è stata usata per secoli per chiarificare le real ale inglesi.', null),
  (48, 'curiosita', 'La gelatina usata a freddo aiuta a rendere più limpida la birra finita.', null),
  (49, 'curiosita', 'Il "chill haze" è una velatura che appare solo quando la birra è fredda, dovuta a proteine e polifenoli.', null),
  (50, 'curiosita', 'Un volume di CO₂ significa che la birra contiene un volume di gas pari al proprio volume liquido.', null),
  (51, 'curiosita', 'Le weizen bavaresi possono arrivare a 3,5–4 volumi di CO₂.', null),
  (52, 'curiosita', 'Le real ale inglesi servite a pompa hanno circa 1–1,5 volumi di CO₂.', null),
  (53, 'curiosita', 'La schiuma si regge grazie a proteine e iso-alfa acidi del luppolo.', null),
  (54, 'curiosita', 'Grassi e detergenti sui bicchieri distruggono la schiuma: un bicchiere "beer clean" è fondamentale.', null),
  (55, 'curiosita', 'Le bollicine che salgono sempre dallo stesso punto del bicchiere nascono da micro-imperfezioni chiamate siti di nucleazione.', null),
  (56, 'curiosita', 'In una Guinness alla spina le bollicine sembrano scendere: è un effetto delle correnti nel bicchiere.', null),
  (57, 'curiosita', 'Le stout alla spina "nitro" usano una miscela di azoto e CO₂ per una schiuma cremosa.', null),
  (58, 'curiosita', 'La widget nelle lattine di stout è una capsula che rilascia gas all''apertura per creare la schiuma.', null),
  (59, 'curiosita', 'La lattina per birra fu introdotta negli Stati Uniti nel 1935.', null),
  (60, 'curiosita', 'Il tappo a corona fu brevettato da William Painter nel 1892.', null),
  (61, 'curiosita', 'Il tappo a corona standard ha 21 "denti".', null),
  (62, 'curiosita', 'Le bottiglie champagnotte resistono a pressioni molto più alte delle normali bottiglie da birra.', null),
  (63, 'curiosita', 'Una bottiglia "beer bomb" è una bottiglia esplosa per eccesso di priming o infezione: attenzione agli zuccheri!', null),
  (64, 'curiosita', 'Una birra bottiglia-condizionata continua a evolvere in bottiglia grazie al lievito residuo.', null),
  (65, 'curiosita', 'Il Reinheitsgebot bavarese del 1516 ammetteva solo acqua, orzo e luppolo: il lievito non era ancora conosciuto.', null),
  (66, 'curiosita', 'Il Reinheitsgebot era anche una misura per riservare il frumento ai fornai.', null),
  (67, 'curiosita', 'In Belgio esistono birre a fermentazione spontanea, i lambic, prodotte nella valle della Senne.', null),
  (68, 'curiosita', 'I lambic vengono inoculati dai microrganismi presenti nell''aria tramite vasche di raffreddamento aperte chiamate coolship.', null),
  (69, 'curiosita', 'Il gueuze è una miscela di lambic giovani e vecchi rifermentata in bottiglia.', null),
  (70, 'curiosita', 'La kriek è un lambic con ciliegie, la framboise con lamponi.', null),
  (71, 'curiosita', 'I lambic usano luppolo invecchiato, per sfruttarne le proprietà conservanti e non l''amaro.', null),
  (72, 'curiosita', 'Il Brettanomyces dà aromi "funky" come cuoio, sudore di cavallo e stalla: amato in alcuni stili, temuto in altri.', null),
  (73, 'curiosita', 'Il Lactobacillus produce acido lattico ed è usato nelle sour come Berliner Weisse e Gose.', null),
  (74, 'curiosita', 'La Gose è una birra tedesca con sale e coriandolo, originaria della città di Goslar.', null),
  (75, 'curiosita', 'La Berliner Weisse veniva spesso servita con sciroppo di lampone o di asperula.', null),
  (76, 'curiosita', 'Napoleone avrebbe definito la Berliner Weisse "lo champagne del Nord" (aneddoto tradizionale).', null),
  (77, 'curiosita', 'Esistono solo una manciata di birrifici trappisti autorizzati a usare il logo "Authentic Trappist Product".', null),
  (78, 'curiosita', 'Una birra trappista deve essere prodotta all''interno o nei pressi di un''abbazia, sotto il controllo dei monaci.', null),
  (79, 'curiosita', 'Secondo una spiegazione popolare (non confermata), i nomi Dubbel e Tripel verrebbero dalle croci segnate sui fusti per indicarne la forza.', null),
  (80, 'curiosita', 'Tre Fontane, vicino a Roma, è l''unica abbazia trappista italiana con birra certificata.', null),
  (81, 'curiosita', 'Lo stile Italian Grape Ale (IGA) prevede l''uso di uva o mosto d''uva: un contributo italiano al mondo della birra.', null),
  (82, 'curiosita', 'L''Italia ha visto nascere i primi birrifici artigianali moderni nel 1996.', null),
  (83, 'curiosita', 'Le IPA nacquero in Inghilterra nel XIX secolo e venivano spedite in India.', null),
  (84, 'curiosita', 'Il mito che le IPA fossero "inventate" apposta per il viaggio in India è una semplificazione: le pale ale molto luppolate esistevano già.', null),
  (85, 'curiosita', 'La porter prende probabilmente il nome dai facchini (porters) di Londra che la bevevano.', null),
  (86, 'curiosita', 'La stout nasce come versione "stout", cioè robusta, della porter.', null),
  (87, 'curiosita', 'La Russian Imperial Stout era esportata verso la corte russa nel Settecento.', null),
  (88, 'curiosita', 'La Märzen prende il nome da marzo, mese in cui veniva prodotta prima della pausa estiva.', null),
  (89, 'curiosita', 'In Baviera era vietato fare birra d''estate per il rischio di incendi e infezioni.', null),
  (90, 'curiosita', 'La Kölsch può chiamarsi così solo se prodotta nella zona di Colonia.', null),
  (91, 'curiosita', 'Le Altbier di Düsseldorf sono ale fermentate e poi maturate al freddo, "alla vecchia maniera".', null),
  (92, 'curiosita', 'Le Rauchbier di Bamberga usano malto affumicato con legno di faggio.', null),
  (93, 'curiosita', 'La Steam Beer californiana fermentava lievito lager a temperature da ale.', null),
  (94, 'curiosita', 'La Hefeweizen è torbida perché non filtrata e ricca di lievito in sospensione.', null),
  (95, 'curiosita', 'La Witbier belga usa frumento non maltato, coriandolo e scorza d''arancia amara.', null),
  (96, 'curiosita', 'La Saison era la birra dei lavoratori stagionali nelle fattorie della Vallonia.', null),
  (97, 'curiosita', 'Il lievito saison è noto per poter attenuare moltissimo, lasciando birre molto secche.', null),
  (98, 'curiosita', 'Le NEIPA sono torbide per la combinazione di proteine, polifenoli dei luppoli e lievito.', null),
  (99, 'curiosita', 'La "biotrasformazione" è la modifica dei composti aromatici del luppolo da parte del lievito in fermentazione.', null),
  (100, 'curiosita', 'Il dry hopping aggiunge aroma senza aggiungere amaro significativo.', null),
  (101, 'curiosita', 'L''"hop creep" è una ripresa di fermentazione causata da enzimi presenti nel luppolo in dry hop.', null),
  (102, 'curiosita', 'Il luppolo Cascade, rilasciato nel 1972, è il simbolo delle American Pale Ale.', null),
  (103, 'curiosita', 'Il Citra, rilasciato nel 2007, ha aromi di agrumi e frutta tropicale.', null),
  (104, 'curiosita', 'Il Saaz è il luppolo nobile ceco per eccellenza, usato nelle Pilsner.', null),
  (105, 'curiosita', 'I quattro luppoli "nobili" tradizionali sono Hallertau Mittelfrüh, Tettnanger, Spalter e Saaz.', null),
  (106, 'curiosita', 'La Nuova Zelanda produce luppoli con note di uva spina e frutto della passione, come il Nelson Sauvin.', null),
  (107, 'curiosita', 'Il nome Nelson Sauvin richiama le note di Sauvignon Blanc che il luppolo ricorda.', null),
  (108, 'curiosita', 'I luppoli vanno conservati sottovuoto e in freezer: gli alfa acidi calano con calore e ossigeno.', null),
  (109, 'curiosita', 'Il "Hop Storage Index" indica quanto un luppolo ha perso freschezza.', null),
  (110, 'curiosita', 'Il malto crystal/caramel viene "stufato" umido, caramellizzando gli zuccheri all''interno del chicco.', null),
  (111, 'curiosita', 'I malti crystal non contengono amidi da convertire: possono essere messi in infusione anche fuori dal mash.', null),
  (112, 'curiosita', 'Il malto acidulato contiene acido lattico ed è usato per abbassare il pH del mash.', null),
  (113, 'curiosita', 'Ogni 1% di malto acidulato abbassa il pH del mash di circa 0,1 punti (regola empirica).', null),
  (114, 'curiosita', 'Il gesso (CaSO₄) esalta la secchezza dell''amaro, il cloruro di calcio (CaCl₂) la rotondità maltata.', null),
  (115, 'curiosita', 'Il rapporto solfati/cloruri è una delle leve più usate per bilanciare il profilo di una birra.', null),
  (116, 'curiosita', 'Il calcio è importante nel mash: aiuta gli enzimi e la flocculazione del lievito.', null),
  (117, 'curiosita', 'Il bicarbonato nell''acqua alza il pH del mash: le acque dure e alcaline si adattano bene alle birre scure.', null),
  (118, 'curiosita', 'I malti scuri sono acidi: per questo Dublino, con acqua alcalina, è diventata patria delle stout.', null),
  (119, 'curiosita', 'Il cloro e le clorammine dell''acqua di rete possono creare clorofenoli dal sapore medicinale.', null),
  (120, 'curiosita', 'Mezza compressa di metabisolfito di potassio (Campden) neutralizza il cloro di circa 75 litri d''acqua.', null),
  (121, 'curiosita', 'Lo sparge troppo caldo (oltre 78 °C) o con pH alto estrae tannini astringenti dalle bucce.', null),
  (122, 'curiosita', 'La "fly sparge" è il risciacquo continuo, la "batch sparge" a lotti: entrambe funzionano bene.', null),
  (123, 'curiosita', 'Il BIAB (Brew In A Bag) usa una sacca per contenere i grani ed evita lo sparge tradizionale.', null),
  (124, 'curiosita', 'L''efficienza di mash in casa varia spesso tra il 65% e l''80%.', null),
  (125, 'curiosita', 'Macinare più fine aumenta l''efficienza ma può bloccare il filtraggio: con il BIAB si può osare di più.', null),
  (126, 'curiosita', 'Il guscio dell''orzo funziona da letto filtrante naturale durante il filtraggio.', null),
  (127, 'curiosita', 'La lolla di riso si aggiunge per evitare filtraggi bloccati con tanto frumento o avena.', null),
  (128, 'curiosita', 'L''avena dà una sensazione setosa al palato grazie ai beta-glucani.', null),
  (129, 'curiosita', 'Un buon mosto di partenza (starter) aiuta il lievito a partire senza stress.', null),
  (130, 'curiosita', 'Il tasso di inoculo consigliato per le lager è circa il doppio di quello per le ale.', null),
  (131, 'curiosita', 'Il lievito secco non ha bisogno di starter, ma una reidratazione corretta lo rende più vitale.', null),
  (132, 'curiosita', 'Il Kveik è un lievito tradizionale norvegese che fermenta pulito anche a 35–40 °C.', null),
  (133, 'curiosita', 'Il Kveik veniva tramandato nelle famiglie norvegesi e conservato essiccato su anelli di legno.', null),
  (134, 'curiosita', 'Il lievito flocculante si deposita rapidamente sul fondo, dando birre più limpide.', null),
  (135, 'curiosita', 'L''attenuazione apparente indica quanta parte degli zuccheri è stata fermentata secondo il densimetro.', null),
  (136, 'curiosita', 'Una FG stabile per tre giorni consecutivi è il segnale classico di fine fermentazione.', null),
  (137, 'curiosita', 'Imbottigliare prima della fine della fermentazione è la causa principale di bottiglie esplosive.', null),
  (138, 'curiosita', 'Lo zucchero da tavola (saccarosio) è perfettamente adatto al priming.', null),
  (139, 'curiosita', 'La birra "verde" appena imbottigliata ha bisogno di almeno 2–3 settimane per carbonarsi bene.', null),
  (140, 'curiosita', 'La temperatura di rifermentazione in bottiglia ideale per una ale è di 18–22 °C.', null),
  (141, 'curiosita', 'La maturazione al freddo (lagering) affina il gusto e chiarifica la birra.', null),
  (142, 'curiosita', 'La parola "lager" viene dal tedesco "lagern", cioè conservare, immagazzinare.', null),
  (143, 'curiosita', 'Il termine "ale" in antico inglese indicava la birra non luppolata.', null),
  (144, 'curiosita', 'La parola "birra" in italiano deriva dal tedesco "Bier".', null),
  (145, 'curiosita', 'La parola spagnola "cerveza" deriva dal latino "cervisia", di origine gallica.', null),
  (146, 'curiosita', 'Ninkasi era la dea sumera della birra: un inno a lei contiene una delle più antiche "ricette".', null),
  (147, 'curiosita', 'La Cechia ha uno dei consumi di birra pro capite più alti al mondo.', null),
  (148, 'curiosita', 'L''Oktoberfest di Monaco nacque nel 1810 per festeggiare un matrimonio reale.', null),
  (149, 'curiosita', 'All''Oktoberfest possono servire birra solo i birrifici di Monaco.', null),
  (150, 'curiosita', 'Il bicchiere Teku, molto usato nei pub artigianali, è stato disegnato in Italia.', null),
  (151, 'curiosita', 'Le birre forti si servono meno fredde: il freddo eccessivo copre gli aromi.', null),
  (152, 'curiosita', 'La temperatura di servizio ideale per una stout è intorno ai 10–13 °C.', null),
  (153, 'curiosita', 'Il sedimento di lievito sul fondo della bottiglia è commestibile e ricco di vitamine del gruppo B.', null),
  (154, 'curiosita', 'Versare la birra inclinando il bicchiere e raddrizzandolo alla fine dà la schiuma giusta.', null),
  (155, 'curiosita', 'Una "session beer" è una birra a bassa gradazione pensata per berne più di una.', null),
  (156, 'curiosita', 'Le Barleywine possono superare il 10% di alcol e invecchiare per anni.', null),
  (157, 'curiosita', 'L''Eisbock si ottiene congelando parzialmente una Doppelbock e togliendo il ghiaccio, per concentrarla.', null),
  (158, 'curiosita', 'Molte Doppelbock tedesche hanno nomi che finiscono in "-ator", in omaggio alla Salvator dei monaci paolani.', null),
  (159, 'curiosita', 'I monaci paolani di Monaco bevevano Doppelbock durante la Quaresima: il "pane liquido".', null),
  (160, 'curiosita', 'I luppoli "aroma" vengono aggiunti a fine bollitura per non disperdere gli oli volatili.', null),
  (161, 'curiosita', 'Il mircene è uno degli oli essenziali più abbondanti nel luppolo e si disperde facilmente con il calore.', null),
  (162, 'curiosita', 'Il linalolo dà note floreali e di lavanda a molti luppoli.', null),
  (163, 'curiosita', 'Il sanitizer a base di acido peracetico o Star San funziona in pochi minuti senza risciacquo.', null),
  (164, 'curiosita', 'Pulire e sanitizzare sono due cose diverse: prima si toglie lo sporco, poi si uccidono i microbi.', null),
  (165, 'curiosita', 'La schiuma dello Star San non è un problema: "don''t fear the foam" dicono gli homebrewer americani.', null),
  (166, 'curiosita', 'Il luppolo cresce in senso orario attorno al suo sostegno.', null),
  (167, 'curiosita', 'Il punto di ebollizione dell''acqua cala con l''altitudine: in montagna la bollitura isomerizza un po'' meno luppolo.', null),
  (168, 'curiosita', 'Le bottiglie da 0,33 L sono il formato più diffuso in Italia per la birra artigianale.', null),
  (169, 'curiosita', 'Le birre ad alta gradazione richiedono più tempo per carbonarsi: il lievito lavora più lentamente in ambiente alcolico.', null),
  (170, 'storia', 'Le prime tracce di produzione di birra risalgono ad almeno 5.000 anni fa in Mesopotamia.', null),
  (171, 'storia', 'In una grotta vicino ad Haifa, in Israele, sono state trovate tracce di bevande fermentate da cereali di circa 13.000 anni fa.', null),
  (172, 'storia', 'I lavoratori delle piramidi di Giza ricevevano birra come parte della loro razione quotidiana.', null),
  (173, 'storia', 'Nell''antico Egitto la birra era così comune da essere usata anche come forma di pagamento.', null),
  (174, 'storia', 'Il Codice di Hammurabi (circa 1750 a.C.) conteneva norme sulle taverne e sulla vendita della birra.', null),
  (175, 'storia', 'L''Inno a Ninkasi, del XIX secolo a.C. circa, è considerato una delle più antiche ricette di birra conosciute.', null),
  (176, 'storia', 'I Sumeri bevevano la birra con lunghe cannucce per evitare i residui di cereali che galleggiavano.', null),
  (177, 'storia', 'Gli antichi Greci e Romani consideravano la birra una bevanda da "barbari", preferendo il vino.', null),
  (178, 'storia', 'Tacito descrisse i Germani come bevitori di una bevanda ottenuta da orzo e frumento "corrotta a somiglianza del vino".', null),
  (179, 'storia', 'Nel Medioevo i monasteri furono tra i principali centri di produzione e perfezionamento della birra.', null),
  (180, 'storia', 'La badessa Ildegarda di Bingen scrisse nel XII secolo del luppolo e delle sue proprietà conservanti.', null),
  (181, 'storia', 'I primi usi documentati del luppolo nella birra risalgono a monasteri germanici del IX secolo.', null),
  (182, 'storia', 'Nel Medioevo la birra leggera ("small beer") era bevuta anche dai bambini, perché più sicura di molte acque.', null),
  (183, 'storia', 'La gilda dei birrai di Monaco ha origini antichissime: i birrifici storici della città vantano secoli di storia.', null),
  (184, 'storia', 'Weihenstephan rivendica il titolo di birrificio più antico al mondo ancora in attività, con origini nel 1040.', null),
  (185, 'storia', 'Il Reinheitsgebot fu promulgato il 23 aprile 1516 a Ingolstadt dai duchi Guglielmo IV e Ludovico X di Baviera.', null),
  (186, 'storia', 'Il 23 aprile in Germania si celebra la Giornata della birra tedesca, in ricordo del Reinheitsgebot.', null),
  (187, 'storia', 'Nel 1553 in Baviera fu vietato produrre birra nei mesi estivi, favorendo le lager fermentate al fresco.', null),
  (188, 'storia', 'I birrai bavaresi conservavano la birra in cantine scavate e raffreddate con il ghiaccio dei laghi.', null),
  (189, 'storia', 'I Padri Pellegrini del Mayflower sbarcarono a Plymouth anche perché, secondo un diario, stavano finendo la birra.', null),
  (190, 'storia', 'Nel 1777 la birreria Bass fu fondata a Burton-on-Trent, diventando un simbolo delle pale ale inglesi.', null),
  (191, 'storia', 'Il triangolo rosso di Bass fu uno dei primi marchi registrati nel Regno Unito, nel 1876.', null),
  (192, 'storia', 'Arthur Guinness firmò nel 1759 un contratto d''affitto di 9.000 anni per il birrificio di St. James''s Gate a Dublino.', null),
  (193, 'storia', 'Nel 1814 a Londra un''enorme cisterna di porter della Meux scoppiò: l''onda di birra uccise otto persone.', null),
  (194, 'storia', 'Il London Beer Flood del 1814 riversò oltre un milione di litri di birra nelle strade di St Giles.', null),
  (195, 'storia', 'Il termometro e il densimetro entrarono nei birrifici inglesi alla fine del Settecento, rendendo la produzione più scientifica.', null),
  (196, 'storia', 'Daniel Wheeler brevettò nel 1817 un tostatore a tamburo che permise di produrre il malto black patent.', null),
  (197, 'storia', 'L''invenzione della refrigerazione artificiale, con Carl von Linde negli anni 1870, cambiò per sempre la produzione delle lager.', null),
  (198, 'storia', 'Carl von Linde sviluppò le sue macchine frigorifere anche grazie al sostegno di birrifici come Spaten.', null),
  (199, 'storia', 'Gabriel Sedlmayr di Spaten e Anton Dreher di Vienna viaggiarono in Inghilterra per studiare le tecniche di maltazione.', null),
  (200, 'storia', 'Anton Dreher creò lo stile Vienna Lager intorno al 1841.', null),
  (201, 'storia', 'Il Proibizionismo negli Stati Uniti durò dal 1920 al 1933.', null),
  (202, 'storia', 'Durante il Proibizionismo molti birrifici americani sopravvissero producendo gelati, malto "per panificazione" e bibite.', null),
  (203, 'storia', 'Nel 1978 il presidente Carter firmò la legge che rese legale l''homebrewing a livello federale negli Stati Uniti.', null),
  (204, 'storia', 'In Italia la produzione casalinga di birra per uso personale è consentita senza licenza, purché non venga venduta.', null),
  (205, 'storia', 'La Campaign for Real Ale (CAMRA) nacque nel Regno Unito nel 1971 per difendere le birre tradizionali.', null),
  (206, 'storia', 'Sierra Nevada Pale Ale, del 1980, ha contribuito a diffondere il luppolo Cascade nel mondo.', null),
  (207, 'storia', 'Anchor Steam di San Francisco è spesso considerata una delle pioniere della rinascita della birra artigianale americana.', null),
  (208, 'storia', 'Fritz Maytag rilevò Anchor Brewing nel 1965, salvandola dalla chiusura.', null),
  (209, 'storia', 'Michael Jackson, il "Beer Hunter", con i suoi libri degli anni ''70 contribuì a far conoscere gli stili birrari nel mondo.', null),
  (210, 'storia', 'Il sistema degli stili birrari moderni deve molto al lavoro di Michael Jackson e poi al BJCP.', null),
  (211, 'storia', 'Il BJCP (Beer Judge Certification Program) nacque negli Stati Uniti nel 1985.', null),
  (212, 'storia', 'In Belgio la cultura della birra è stata riconosciuta dall''UNESCO come patrimonio culturale immateriale nel 2016.', null),
  (213, 'storia', 'Westvleteren, una delle birre trappiste più ricercate, è stata a lungo venduta quasi solo all''abbazia su prenotazione.', null),
  (214, 'storia', 'Orval è prodotta nell''abbazia di Notre-Dame d''Orval, la cui leggenda parla di un anello d''oro restituito da una trota.', null),
  (215, 'storia', 'Chimay, nel Belgio meridionale, produce birra dal 1862.', null),
  (216, 'storia', 'La birra Peroni nacque a Vigevano nel 1846, prima di trasferirsi a Roma.', null),
  (217, 'storia', 'Birra Moretti fu fondata a Udine nel 1859 da Luigi Moretti.', null),
  (218, 'storia', 'Il "baffo" di Birra Moretti deriva da una fotografia scattata negli anni ''40 a un signore in una trattoria.', null),
  (219, 'storia', 'Nel 1842 la birra di Plzeň diventò la prima lager dorata: prima le lager erano scure.', null),
  (220, 'storia', 'Il vetro trasparente diventò economico nell''Ottocento: le birre dorate divennero "belle da vedere" e conquistarono il mondo.', null),
  (221, 'storia', 'Fino all''Ottocento gran parte della birra si beveva da boccali opachi di peltro, ceramica o legno.', null),
  (222, 'storia', 'Nella Londra del Settecento la porter era la birra più bevuta e veniva invecchiata in enormi tini.', null),
  (223, 'storia', 'Gli inglesi chiamavano "entire" la porter ottenuta da un unico mosto, invece di miscelare birre diverse.', null),
  (224, 'storia', 'Le prime IPA arrivavano in India dopo mesi di viaggio intorno al Capo di Buona Speranza.', null),
  (225, 'storia', 'George Hodgson, birraio di Bow a Londra, fu tra i primi a esportare pale ale in India nel Settecento.', null),
  (226, 'storia', 'I vichinghi bevevano birra e idromele: nella mitologia norrena il Valhalla è pieno di bevande.', null),
  (227, 'storia', 'Nel Medioevo in Inghilterra gli "ale-conner" erano ispettori incaricati di controllare qualità e prezzo della birra.', null),
  (228, 'storia', 'In molte città medievali il birraio era spesso una donna: le "alewives" producevano e vendevano la birra.', null),
  (229, 'storia', 'Nel 1857 Louis Pasteur iniziò a dimostrare che la fermentazione è opera di microrganismi viventi.', null),
  (230, 'storia', 'Eduard Buchner ricevette il Nobel per la chimica nel 1907 per aver dimostrato la fermentazione senza cellule vive.', null),
  (231, 'storia', 'La parola "enzima" fu coniata nel 1877 da Wilhelm Kühne e significa "nel lievito".', null),
  (232, 'storia', 'I Celti producevano birra di frumento e orzo già prima della conquista romana.', null),
  (233, 'storia', 'Plinio il Vecchio cita una pianta, probabilmente il luppolo, come ortaggio: i germogli si mangiavano.', null),
  (234, 'storia', 'I germogli di luppolo selvatico, i "bruscandoli", sono ancora oggi un ingrediente di risotti e frittate in Veneto.', null),
  (235, 'storia', 'Il primo birrificio industriale in Italia si sviluppò nel XIX secolo soprattutto nel Nord, vicino all''arco alpino.', null),
  (236, 'storia', 'Nel Seicento in Inghilterra i salari dei lavoratori agricoli includevano spesso una razione di birra.', null),
  (237, 'storia', 'Durante la Seconda guerra mondiale la birra fu considerata un bene essenziale per il morale delle truppe britanniche.', null),
  (238, 'storia', 'La prima birra in lattina venduta fu prodotta dalla Krueger Brewing Company del New Jersey nel 1935.', null),
  (239, 'consiglio', 'Prima di ogni cotta, calibra il densimetro con acqua alla temperatura indicata sullo strumento.', null),
  (240, 'consiglio', 'Misura il pH del mash dopo 10–15 minuti dall''impasto, quando si è stabilizzato.', null),
  (241, 'consiglio', 'Raffredda il campione prima di misurare il pH: il valore cambia con la temperatura.', null),
  (242, 'consiglio', 'Tieni sempre a portata di mano un secchio di sanitizzante: ogni cosa che tocca il mosto freddo va sanitizzata.', null),
  (243, 'consiglio', 'Raffredda il mosto il più in fretta possibile: meno tempo a temperature tiepide, meno rischi di infezione.', null),
  (244, 'consiglio', 'Ossigena bene il mosto freddo prima di inoculare il lievito: il lievito ringrazierà.', null),
  (245, 'consiglio', 'Controlla la temperatura del mosto, non solo quella della stanza: in piena fermentazione può salire di diversi gradi.', null),
  (246, 'consiglio', 'I primi 3 giorni di fermentazione sono quelli che definiscono il profilo: tieni la temperatura sotto controllo.', null),
  (247, 'consiglio', 'Non aprire il fermentatore solo per curiosità: ogni apertura è un rischio di ossidazione e contaminazione.', null),
  (248, 'consiglio', 'Il gorgogliatore non è un densimetro: l''unico modo per sapere se la fermentazione è finita è misurare la densità.', null),
  (249, 'consiglio', 'Aspetta che la FG sia stabile per almeno due o tre giorni prima di imbottigliare.', null),
  (250, 'consiglio', 'Annota tutto: ciò che non è scritto, non è successo. E BrewPastore è qui apposta!', null),
  (251, 'consiglio', 'Pesa lo zucchero di priming con una bilancia di precisione, non a cucchiai.', null),
  (252, 'consiglio', 'Sciogli lo zucchero di priming in poca acqua bollita e mescolalo delicatamente alla birra prima di imbottigliare.', null),
  (253, 'consiglio', 'Nel calcolo del priming considera la temperatura massima raggiunta a fine fermentazione: lì si è stabilita la CO₂ residua.', null),
  (254, 'consiglio', 'Lascia circa 2–3 cm di spazio di testa nelle bottiglie.', null),
  (255, 'consiglio', 'Conserva le bottiglie in piedi: il lievito si deposita sul fondo e non sul collo.', null),
  (256, 'consiglio', 'Dopo la rifermentazione, metti le bottiglie al fresco per qualche giorno: la birra diventa più limpida.', null),
  (257, 'consiglio', 'Versa la birra lasciando l''ultimo centimetro di lievito in bottiglia, a meno che non sia una weizen.', null),
  (258, 'consiglio', 'Sciacqua le bottiglie subito dopo averle svuotate: si puliscono molto più facilmente.', null),
  (259, 'consiglio', 'Usa un ponticello o un tubo con valvola per riempire le bottiglie dal fondo, riducendo l''ossidazione.', null),
  (260, 'consiglio', 'Il luppolo in dry hop dà il meglio dopo 2–4 giorni: troppo a lungo può dare note erbacee.', null),
  (261, 'consiglio', 'Fai dry hop a fine fermentazione attiva, o verso la fine, per sfruttare la CO₂ che scaccia l''ossigeno.', null),
  (262, 'consiglio', 'Conserva luppoli e lieviti secchi in frigo o freezer, sottovuoto.', null),
  (263, 'consiglio', 'Il lievito liquido ha una data: controlla la vitalità e prepara uno starter se è vecchio.', null),
  (264, 'consiglio', 'Reidrata il lievito secco in acqua a circa 25–30 °C per 15–30 minuti, se lo preferisci al lancio diretto.', null),
  (265, 'consiglio', 'Un mosto molto denso ha bisogno di più lievito: per birre forti valuta due bustine o uno starter.', null),
  (266, 'consiglio', 'Non buttare il lievito sul fondo del fermentatore: puoi raccoglierlo e riusarlo per la cotta successiva.', null),
  (267, 'consiglio', 'Se il mash pH è troppo alto, l''acido lattico agisce rapidamente: aggiungilo poco per volta e rimisura.', null),
  (268, 'consiglio', 'Le correzioni dell''acqua si calcolano meglio partendo da un''analisi dell''acqua: chiedila al gestore o falla fare.', null),
  (269, 'consiglio', 'Per le birre chiare, un''acqua troppo dura e alcalina va diluita o corretta.', null),
  (270, 'consiglio', 'Il gesso esalta l''amaro dei luppoli: ottimo per IPA e pale ale, da evitare nelle birre delicate.', null),
  (271, 'consiglio', 'Il cloruro di calcio dà rotondità: è amico delle NEIPA e delle birre maltate.', null),
  (272, 'consiglio', 'Controlla sempre la densità pre-boil: se è bassa puoi allungare la bollitura o aggiungere estratto.', null),
  (273, 'consiglio', 'Una bollitura di 60 minuti basta per la maggior parte delle birre; per malti Pilsner molti preferiscono 90 minuti.', null),
  (274, 'consiglio', 'Tieni il coperchio della pentola sollevato in bollitura, per far evaporare il DMS.', null),
  (275, 'consiglio', 'Aggiungi l''Irish moss o il Whirlfloc negli ultimi 10–15 minuti di bollitura.', null),
  (276, 'consiglio', 'Le prime cotte di una nuova ricetta servono a calibrare l''impianto: confronta efficienza e volumi reali con quelli previsti.', null),
  (277, 'consiglio', 'Calcola la tua efficienza reale ad ogni cotta: dopo qualche batch le ricette diventeranno precisissime.', null),
  (278, 'consiglio', 'Pesa i grani due volte: un errore di 500 g cambia l''OG in modo significativo.', null),
  (279, 'consiglio', 'Macina i malti poco prima della cotta: il malto macinato si ossida e perde freschezza.', null),
  (280, 'consiglio', 'Per un mash stabile, preriscalda la pentola o il tino prima di aggiungere acqua e grani.', null),
  (281, 'consiglio', 'L''impasto va mescolato bene per evitare grumi di farina secca ("dough balls").', null),
  (282, 'consiglio', 'Fai una prova dello iodio se hai dubbi sulla conversione: se diventa blu-nera c''è ancora amido.', null),
  (283, 'consiglio', 'Usa una lista di controllo stampata il giorno della cotta: niente dimenticanze su luppoli e tempi.', null),
  (284, 'consiglio', 'Prepara tutti gli ingredienti pesati e divisi prima di accendere il fuoco ("mise en place" del birraio).', null),
  (285, 'consiglio', 'Non riempire il fermentatore fino all''orlo: lascia spazio al krausen, o finirà nel gorgogliatore.', null),
  (286, 'consiglio', 'Se fermenti caldo, una blow-off tube ti salva da un soffitto ricoperto di schiuma.', null),
  (287, 'consiglio', 'Un fermentatore in un bagno d''acqua con una bottiglia congelata è il frigo da fermentazione più economico.', null),
  (288, 'consiglio', 'Per le lager, il riposo del diacetile a 18–20 °C per 2–3 giorni a fine fermentazione fa miracoli.', null),
  (289, 'consiglio', 'Fai un cold crash di 2–3 giorni prima dell''imbottigliamento per una birra più limpida.', null),
  (290, 'consiglio', 'Durante il cold crash il fermentatore può risucchiare l''acqua del gorgogliatore: occhio all''aria e al sanitizzante.', null),
  (291, 'consiglio', 'Ogni guarnizione e rubinetto va smontato e pulito: è lì che si nascondono le infezioni.', null),
  (292, 'consiglio', 'Non usare spugne abrasive sulla plastica dei fermentatori: i graffi ospitano batteri.', null),
  (293, 'consiglio', 'Il PBW o il percarbonato sono ottimi per pulire: ammollo in acqua calda e lo sporco viene via da solo.', null),
  (294, 'consiglio', 'Assaggia la birra a ogni misura di densità: impari tantissimo su come evolve.', null),
  (295, 'consiglio', 'Tieni un campione della birra finita da riassaggiare dopo qualche mese: scoprirai come invecchia.', null),
  (296, 'consiglio', 'Cambia una sola variabile per volta tra due cotte della stessa ricetta: solo così capisci cosa ha fatto la differenza.', null),
  (297, 'consiglio', 'Fai assaggiare la birra alla cieca agli amici: il giudizio sarà più sincero.', null),
  (298, 'consiglio', 'Le birre luppolate vanno bevute fresche: l''aroma del luppolo cala in poche settimane.', null),
  (299, 'consiglio', 'Le birre scure e forti invece migliorano con qualche mese di cantina.', null),
  (300, 'consiglio', 'Non servire la birra troppo fredda: sotto i 4 °C i sapori si spengono.', null),
  (301, 'consiglio', 'Lava i bicchieri da birra senza brillantante: lascia residui che uccidono la schiuma.', null),
  (302, 'consiglio', 'Sciacqua il bicchiere con acqua fredda prima di versare: la schiuma sarà più fine.', null),
  (303, 'consiglio', 'Etichetta ogni bottiglia con batch e data: tra sei mesi non ricorderai cosa c''è dentro.', null),
  (304, 'consiglio', 'Un tappo dalla corona storta è un tappo che perde: controlla ogni bottiglia dopo la tappatura.', null),
  (305, 'consiglio', 'Tieni una "bottiglia spia" in PET: quando è dura come un sasso, le altre sono carbonate.', null),
  (306, 'consiglio', 'Quando una ricetta viene benissimo, duplicala in BrewPastore prima di modificarla.', null),
  (307, 'consiglio', 'Registra anche gli errori: nel diario del batch valgono più dei successi.', null),
  (308, 'consiglio', 'Per un''IPA più secca, abbassa la temperatura di mash di 1–2 gradi o aggiungi un po'' di destrosio.', null),
  (309, 'consiglio', 'Per più corpo, alza la temperatura di mash o aggiungi malti destrinici come il Carapils.', null),
  (310, 'consiglio', 'L''avena e il frumento migliorano la tenuta della schiuma.', null),
  (311, 'consiglio', 'Un pizzico di sale (pochi grammi per batch) nella Gose è parte dello stile, non un errore.', null),
  (312, 'consiglio', 'Per sour con Lactobacillus, abbassa prima il pH del mosto sotto 4,5 per scoraggiare batteri indesiderati.', null),
  (313, 'consiglio', 'Tieni attrezzatura separata (tubi, guarnizioni) per le birre acide con batteri e Brettanomyces.', null),
  (314, 'consiglio', 'Le spezie si aggiungono a fine bollitura o in fermentazione, ma sempre con moderazione: si possono aggiungere, non togliere.', null),
  (315, 'consiglio', 'Per la frutta in fermentazione, meglio congelarla prima: le cellule si rompono e rilascia più aroma.', null),
  (316, 'consiglio', 'Usa sempre una pentola abbastanza grande: un boil-over sul fornello è un incubo da pulire.', null),
  (317, 'consiglio', 'Raffreddare il mosto in estate è più lento: prevedi una pompa con acqua ghiacciata nel secondo passaggio.', null),
  (318, 'consiglio', 'Il serpentino di raffreddamento va immerso nel mosto bollente negli ultimi 10 minuti per sanitizzarlo.', null),
  (319, 'consiglio', 'Controlla il volume finale nel fermentatore e annotalo: serve per calcolare costi per litro e priming.', null),
  (320, 'consiglio', 'Ricordati di segnare i kWh consumati: con un contatore da presa scoprirai quanto costa davvero la cotta.', null),
  (321, 'consiglio', 'Confronta i prezzi dei fornitori su BrewPastore: il costo medio ti dirà quando conviene fare scorta.', null),
  (322, 'consiglio', 'Comprare malti base in sacchi da 25 kg di solito abbassa molto il costo per batch.', null),
  (323, 'consiglio', 'Dividi la spesa subito dopo l''acquisto: i conti chiari mantengono l''amicizia e la birra.', null),
  (324, 'consiglio', 'Il kit di base perfetto: pentola, fermentatore, densimetro, termometro, sanitizzante. Il resto viene dopo.', null),
  (325, 'consiglio', 'Un buon termometro digitale è l''investimento più sottovalutato dall''homebrewer.', null),
  (326, 'consiglio', 'Tieni il pH-metro con la sonda sempre umida nella soluzione di conservazione, non in acqua distillata.', null),
  (327, 'consiglio', 'Calibra il pH-metro con le soluzioni tampone 4 e 7 prima di ogni cotta importante.', null),
  (328, 'consiglio', 'Non lasciare la birra sul fondo di lievito per mesi: l''autolisi può dare sapori di carne e brodo.', null),
  (329, 'consiglio', 'Per un travaso senza ossigeno, flussa il fermentatore di destinazione con CO₂ se ce l''hai.', null),
  (330, 'consiglio', 'Una ricetta semplice fatta bene batte una ricetta complicata fatta male.', null),
  (331, 'consiglio', 'Pochi malti, un luppolo, un lievito: le ricette SMaSH sono ottime per imparare a conoscere gli ingredienti.', null),
  (332, 'consiglio', 'Assaggia i malti crudi prima di usarli: ti danno un''idea di cosa porteranno alla birra.', null),
  (333, 'consiglio', 'Strofina un pellet di luppolo tra le mani e annusalo: è il modo migliore per capirne l''aroma.', null),
  (334, 'consiglio', 'Rispetta i tempi di maturazione delle lager: la pazienza è l''ingrediente più costoso.', null),
  (335, 'consiglio', 'Quando sei in dubbio, aspetta. La birra quasi mai peggiora per qualche giorno in più in fermentatore.', null),
  (336, 'consiglio', 'Se la fermentazione non parte entro 48 ore, controlla temperatura e data del lievito prima di preoccuparti.', null),
  (337, 'consiglio', 'Non tutte le velature sono infezioni: lievito e proteine in sospensione sono normali nelle prime settimane.', null),
  (338, 'consiglio', 'Una pellicola bianca e increspata sulla birra è un pellicle: segno di microrganismi selvaggi, valuta se imbottigliare.', null),
  (339, 'consiglio', 'Fai sempre una foto al densimetro: è la prova regina quando i ricordi divergono.', null),
  (340, 'consiglio', 'Per le birre da invecchiare, usa bottiglie scure e tappi nuovi.', null),
  (341, 'consiglio', 'Il frigo del garage può diventare un''ottima camera di fermentazione con un termostato esterno.', null),
  (342, 'consiglio', 'Pianifica le cotte a ritroso dalla data in cui vuoi berle: una lager per Natale va fatta a ottobre.', null),
  (343, 'consiglio', 'Ogni cotta è una lezione: la prossima sarà migliore.', null),
  (344, 'consiglio', 'Pulisci subito dopo la cotta, quando sei stanco: domani sarà peggio.', null),
  (345, 'proverbio', 'Chi sanitizza bene, imbottiglia meglio.', null),
  (346, 'proverbio', 'Mosto che bolle non teme infezione; mosto tiepido sì.', null),
  (347, 'proverbio', 'La pazienza del birraio si misura in settimane, non in giorni.', null),
  (348, 'proverbio', 'Densità stabile, birraio tranquillo.', null),
  (349, 'proverbio', 'Chi ha fretta di imbottigliare, raccoglie vetri.', null),
  (350, 'proverbio', 'Il lievito fa la birra, il birraio fa solo il mosto.', null),
  (351, 'proverbio', 'Senza acqua buona non c''è birra buona.', null),
  (352, 'proverbio', 'Un malto fresco vale più di dieci ricette.', null),
  (353, 'proverbio', 'Cotta annotata, cotta ripetibile.', null),
  (354, 'proverbio', 'Chi misura il pH non teme l''astringenza.', null),
  (355, 'proverbio', 'Meglio un giorno in più in fermentatore che una bottiglia in meno sullo scaffale.', null),
  (356, 'proverbio', 'Il fondo del fermentatore non si beve, si ricicla.', null),
  (357, 'proverbio', 'Luppolo in bollitura amareggia, luppolo a freddo profuma.', null),
  (358, 'proverbio', 'Ogni birra ha il suo tempo, come ogni stagione ha il suo stile.', null),
  (359, 'proverbio', 'D''estate saison, d''inverno stout, e il birraio è contento in ogni stagione.', null),
  (360, 'proverbio', 'Pulisci oggi, cotta serena domani.', null),
  (361, 'proverbio', 'Chi travasa con l''ossigeno, beve cartone.', null),
  (362, 'proverbio', 'La schiuma è la corona della birra: va conquistata, non spruzzata.', null),
  (363, 'proverbio', 'Una birra condivisa è una birra raddoppiata.', null),
  (364, 'proverbio', 'Tre soci, un fermentatore: tutti contenti se i conti sono chiari.', null),
  (365, 'proverbio', 'Patti chiari, birra lunga.', null),
  (366, 'proverbio', 'Chi divide la spesa, moltiplica gli amici.', null),
  (367, 'proverbio', 'Conto saldato, brindisi meritato.', null),
  (368, 'proverbio', 'Il birraio saggio segna, il birraio stolto ricorda.', null),
  (369, 'proverbio', 'Dove c''è birra fatta in casa, c''è casa.', null),
  (370, 'proverbio', 'La miglior birra è quella che hai fatto tu, la seconda è quella che ti offrono.', null),
  (371, 'proverbio', 'Chi non assaggia, non impara.', null),
  (372, 'proverbio', 'Mosto ben raffreddato, lievito fortunato.', null),
  (373, 'proverbio', 'Lievito felice, birra felice.', null),
  (374, 'proverbio', 'Il termometro non mente, il birraio a volte sì.', null),
  (375, 'proverbio', 'Ricetta semplice, risultato sincero.', null),
  (376, 'proverbio', 'Non c''è IPA senza luppolo, né birraio senza dubbi.', null),
  (377, 'proverbio', 'Il malto dà l''anima, il luppolo il carattere, il lievito la personalità.', null),
  (378, 'proverbio', 'Birra giovane, giudizio sospeso.', null),
  (379, 'proverbio', 'Lager di fretta, lager imperfetta.', null),
  (380, 'proverbio', 'Al freddo la lager si affina, al caldo il birraio si agita.', null),
  (381, 'proverbio', 'Chi semina orzo raccoglie birra.', null),
  (382, 'proverbio', 'Bollitura scoperta, DMS sconfitto.', null),
  (383, 'proverbio', 'Il gorgogliatore chiacchiera, il densimetro parla.', null),
  (384, 'proverbio', 'Bottiglia scura, birra sicura.', null),
  (385, 'proverbio', 'Tappo storto, birra piatta.', null),
  (386, 'proverbio', 'Spazio di testa giusto, carbonazione giusta.', null),
  (387, 'proverbio', 'Chi imbottiglia sporco, beve aceto.', null),
  (388, 'proverbio', 'Il primo sorso è dell''occhio, il secondo del naso, il terzo del cuore.', null),
  (389, 'proverbio', 'Birra fatta con amore, non ha bisogno di filtri.', null),
  (390, 'proverbio', 'Meglio un luppolo fresco oggi che un sacco vecchio domani.', null),
  (391, 'proverbio', 'Ogni errore è un ingrediente della prossima cotta.', null),
  (392, 'proverbio', 'Chi ha il malto ha il pane, chi ha il luppolo ha la festa.', null),
  (393, 'proverbio', 'Una cotta al mese toglie la malinconia di torno.', null),
  (394, 'proverbio', 'Dove finisce la cotta, comincia l''attesa.', null),
  (395, 'proverbio', 'L''attesa del birraio è la gioia del bevitore.', null),
  (396, 'proverbio', 'Il birraio non invecchia: matura.', null),
  (397, 'proverbio', 'Non giudicare una birra dall''etichetta, giudicala dal bicchiere.', null),
  (398, 'proverbio', 'Chi beve birra da solo assaggia, chi la beve in compagnia festeggia.', null),
  (399, 'proverbio', 'Il buon birraio pulisce più di quanto produca.', null),
  (400, 'proverbio', 'Grano macinato oggi, efficienza domani.', null),
  (401, 'proverbio', 'Mash a bassa temperatura, birra secca; mash alto, birra morbida.', null),
  (402, 'proverbio', 'Al birraio non manca mai una scusa per una nuova cotta.', null),
  (403, 'proverbio', 'Una bottiglia aperta è un consiglio, una bottiglia regalata è un''amicizia.', null),
  (404, 'proverbio', 'Se la birra è venuta male, la prossima verrà meglio. Se è venuta bene, rifalla uguale.', null),
  (405, 'battuta', 'Il mio medico mi ha detto di bere più liquidi. Ho scelto quelli fermentati.', null),
  (406, 'battuta', 'Non sono ubriaco, sto solo controllando l''attenuazione apparente.', null),
  (407, 'battuta', 'Ho chiesto al lievito se era stanco. Mi ha risposto: "Sono esausto, ho finito gli zuccheri".', null),
  (408, 'battuta', 'Perché il luppolo non va mai in palestra? Perché è già abbastanza amaro.', null),
  (409, 'battuta', 'Il birraio a dieta? Solo birre a bassa densità.', null),
  (410, 'battuta', '"Quanto ci metti a fare la birra?" "Sei settimane." "E a berla?" "Un pomeriggio."', null),
  (411, 'battuta', 'La mia ragazza dice che passo troppo tempo con il fermentatore. Almeno lui fa le bollicine per me.', null),
  (412, 'battuta', 'Non ho problemi con la birra: ho problemi senza birra.', null),
  (413, 'battuta', 'Homebrewer: persona che spende 500 euro di attrezzatura per risparmiare sulla birra.', null),
  (414, 'battuta', 'Il bello di fare la birra in casa è che risparmi un sacco… sulle birre che non compri mentre aspetti la tua.', null),
  (415, 'battuta', 'Un lievito entra in un bar. Il barista: "Cosa prendi?" Il lievito: "Tutto lo zucchero che hai".', null),
  (416, 'battuta', 'Qual è il colmo per un birraio? Avere un carattere spumeggiante ma una birra piatta.', null),
  (417, 'battuta', 'Qual è il colmo per un lievito? Lavorare tanto e farsi chiamare "sedimento".', null),
  (418, 'battuta', 'Ho provato a fare una birra analcolica. Il lievito ha chiesto il trasferimento.', null),
  (419, 'battuta', 'La birra è come l''amicizia: va condivisa, ma ognuno porta il suo bicchiere.', null),
  (420, 'battuta', 'Non chiedermi di uscire durante il giorno della cotta: ho un appuntamento con il mash.', null),
  (421, 'battuta', '"Che lavoro fai?" "Faccio il pastore." "Di pecore?" "No, di lieviti."', null),
  (422, 'battuta', 'Il mio densimetro dice 1,010. Io dico che è ora di assaggiare.', null),
  (423, 'battuta', 'Dicono che il denaro non compra la felicità. Però compra il malto, che è quasi la stessa cosa.', null),
  (424, 'battuta', 'La birra fatta in casa ha due fasi: "non è ancora pronta" e "è finita".', null),
  (425, 'battuta', 'Ho contato le bottiglie: erano 50. Poi sono passati gli amici: erano 50 vuote.', null),
  (426, 'battuta', 'Il mio impianto è come me: un po'' rattoppato, ma fa ancora il suo lavoro.', null),
  (427, 'battuta', 'Non c''è niente di più ottimista di un birraio che compra il secondo fermentatore "per sicurezza".', null),
  (428, 'battuta', 'Pulire è il 90% del lavoro di un birraio. L''altro 10% è dire agli amici che si fa la birra.', null),
  (429, 'battuta', 'Fare la birra è facile: basta pulire, aspettare, pulire, aspettare e pulire ancora.', null),
  (430, 'battuta', 'L''IPA è come il gossip: va consumata fresca, altrimenti perde aroma.', null),
  (431, 'battuta', 'La stout è la birra perfetta per l''inverno. E per la primavera. E per l''estate.', null),
  (432, 'battuta', 'Il luppolo è la lavanda del birraio: profuma tutto, anche le mani per tre giorni.', null),
  (433, 'battuta', '"La birra fa la pancia." "No, la pancia è un fermentatore di riserva."', null),
  (434, 'battuta', 'Non è un problema di alcol, è un progetto di ricerca sul lievito.', null),
  (435, 'battuta', 'Ho un rapporto serio con la mia birra: ci vediamo tutti i giorni e non litighiamo mai.', null),
  (436, 'battuta', 'Mia nonna diceva: "Chi va piano va sano e va lontano". Era chiaramente una lager.', null),
  (437, 'battuta', 'Il mio motto: prima la sanitizzazione, poi la conversazione.', null),
  (438, 'battuta', '"Perché il fermentatore fa blub blub?" "Ti sta dicendo che ha quasi finito, ma non fidarti."', null),
  (439, 'battuta', 'La differenza tra un birraio e un chimico? Il chimico non beve i suoi esperimenti.', null),
  (440, 'battuta', 'Ho chiamato il mio fermentatore "Ufficio": così posso dire che sto lavorando.', null),
  (441, 'battuta', 'Volevo fare una dieta detox. Poi ho scoperto che il luppolo è una pianta.', null),
  (442, 'battuta', 'La birra contiene orzo, che è un cereale. Quindi tecnicamente è colazione.', null),
  (443, 'battuta', 'La birra è fatta di cereali, acqua e piante: praticamente è un''insalata liquida.', null),
  (444, 'battuta', 'Il mio cardiologo dice che devo fare movimento: ora porto i sacchi di malto a mano.', null),
  (445, 'battuta', '"Cosa hai fatto nel weekend?" "Ho bollito 30 litri di zuppa d''orzo e ho aspettato."', null),
  (446, 'battuta', 'La birra è la prova che l''umanità sa aspettare, quando ne vale la pena.', null),
  (447, 'battuta', 'Ho scritto una ricetta per una birra a 15 gradi. Il lievito ha scritto una lettera di dimissioni.', null),
  (448, 'battuta', 'Il mio lievito preferito? Quello che lavora mentre dormo.', null),
  (449, 'battuta', 'Fare il dry hop è come profumare la casa: alla fine profuma solo il birraio.', null),
  (450, 'battuta', 'Il vero lusso? Avere un frigorifero solo per la birra. Il vero sogno? Averne due.', null),
  (451, 'battuta', '"Hai bevuto troppo?" "No, ho solo testato il prodotto per il controllo qualità."', null),
  (452, 'battuta', 'Un homebrewer non ha mai abbastanza bottiglie. Ha solo troppe birre.', null),
  (453, 'battuta', 'Non posso venire alla festa, la mia birra è in fase di diacetile.', null),
  (454, 'battuta', '"Hai fatto tu questa birra?" è il complimento più bello. "L''hai fatta davvero tu?" il più sospetto.', null),
  (455, 'battuta', 'Gli amici veri ti aiutano a imbottigliare. Gli amici veri veri ti aiutano anche a lavare le bottiglie.', null),
  (456, 'battuta', 'Ogni volta che qualcuno dice "è solo birra", un lievito perde la motivazione.', null),
  (457, 'battuta', 'Il fermentatore è l''unico posto in casa dove le bollicine sono un buon segno.', null),
  (458, 'battuta', 'Io e il mio pH-metro abbiamo una relazione complicata: lui vuole essere calibrato, io voglio bere.', null),
  (459, 'battuta', 'La matematica del birraio: 20 litri di birra = 60 bottiglie = 2 settimane con gli amici.', null),
  (460, 'battuta', 'La matematica del socio: 3 soci, 60 bottiglie = 20 bottiglie a testa. La matematica reale: dipende da chi arriva prima.', null),
  (461, 'battuta', 'Si dice che il vino migliori invecchiando. La birra invece migliora condividendola.', null),
  (462, 'battuta', 'L''acqua è fondamentale per la salute. Infatti la birra ne contiene più del 90%.', null),
  (463, 'battuta', 'Ho sbagliato la ricetta ed è uscita buonissima. Ora non so più come rifarla.', null),
  (464, 'battuta', 'Prima regola del club della birra: si parla sempre della birra.', null),
  (465, 'battuta', 'Chi trova un amico trova un tesoro. Chi trova un amico birraio trova una cantina.', null),
  (466, 'battuta', 'Il mio mash era così stabile che gli ho offerto un contratto a tempo indeterminato.', null),
  (467, 'battuta', 'Mia moglie dice che ho troppe pentole. Io dico che ho una pentola e tanti progetti.', null),
  (468, 'battuta', 'Al corso di yoga ho chiesto qual è la posizione migliore. Hanno detto "il loto". Io pensavo "il divano con una pils".', null),
  (469, 'battuta', 'Non sono testardo: sto solo aspettando che la FG mi dia ragione.', null),
  (470, 'battuta', '"Quanto alcol ha?" "Abbastanza per renderti simpatico, non abbastanza da renderti ministro."', null),
  (471, 'battuta', 'La cosa più rumorosa del mondo? Un tappo che salta alle 3 di notte in cantina.', null),
  (472, 'battuta', 'Il silenzio dopo la cotta è il suono più bello: significa che il lievito sta lavorando e tu puoi riposare.', null),
  (473, 'battuta', '"Vuoi una birra?" è la domanda più facile del mondo. La più difficile è "quale?".', null),
  (474, 'battuta', 'Ho chiesto all''IPA se era amara. Mi ha risposto: "Dipende da quanti IBU mi hai dato".', null),
  (475, 'battuta', 'Il malto tostato va d''accordo con tutti. Il malto bruciato no: è un po'' carbone.', null),
  (476, 'battuta', 'L''efficienza del mio impianto è come il meteo: variabile, ma sempre interessante.', null),
  (477, 'battuta', 'Quando dico "una birra veloce" intendo "una birra veloce da bere", non da fare.', null),
  (478, 'battuta', 'La mia birra non è torbida: è "stile New England".', null),
  (479, 'battuta', 'La mia birra non è acida: è "un esperimento selvaggio".', null),
  (480, 'battuta', 'La mia birra non è piatta: è "servita alla maniera inglese".', null),
  (481, 'battuta', 'Il lievito non ha weekend: per questo è il miglior collega del mondo.', null),
  (482, 'battuta', 'Il bello della birra fatta in casa? Ogni bottiglia ha una storia. Il brutto? Alcune storie sono horror.', null),
  (483, 'battuta', 'Il birraio è l''unico che si emoziona guardando una schiuma marrone in un secchio.', null),
  (484, 'citazione', 'La birra è la prova che Dio ci ama e vuole che siamo felici.', 'attribuita (erroneamente) a Benjamin Franklin, che in realtà parlava del vino'),
  (485, 'citazione', 'Chi beve birra si addormenta presto; chi dorme a lungo non pecca; chi non pecca va in Paradiso.', 'detto popolare di origine medievale'),
  (486, 'citazione', 'Relax, don''t worry, have a homebrew. (Rilassati, non preoccuparti, fatti una birra fatta in casa.)', 'Charlie Papazian, The Complete Joy of Homebrewing'),
  (487, 'citazione', 'Hopfen und Malz – Gott erhalt''s! è il saluto tradizionale delle corporazioni di birrai tedeschi.', 'tradizione tedesca'),
  (488, 'citazione', 'Sprecht vom Bier nicht schlecht: non parlate male della birra.', 'detto tedesco'),
  (489, 'citazione', 'Bier auf Wein, das lass sein; Wein auf Bier, das rat'' ich dir. (Birra dopo vino, lascia stare; vino dopo birra, te lo consiglio.)', 'proverbio tedesco'),
  (490, 'citazione', 'In vino veritas, in cervisia… felicitas!', 'motto goliardico'),
  (491, 'citazione', 'Il birraio che non assaggia la propria birra non merita di farla.', 'massima da cantina'),
  (492, 'citazione', 'La birra è il pane liquido.', 'definizione tradizionale dei monaci bavaresi'),
  (493, 'citazione', 'Prosit! — dal latino "prosit", cioè "che giovi", il brindisi tedesco augura salute.', 'etimologia'),
  (494, 'citazione', 'Cin cin! — l''espressione italiana deriverebbe dal cinese "qing qing", un invito cortese a servirsi.', 'etimologia popolare'),
  (495, 'citazione', 'Skål! — il brindisi scandinavo significa letteralmente "ciotola".', 'etimologia'),
  (496, 'citazione', 'Santé! Na zdraví! Salud! In quasi tutte le lingue il brindisi augura la stessa cosa: salute.', 'tradizione universale'),
  (497, 'citazione', 'Sláinte! — il brindisi irlandese e scozzese vuol dire "salute" in gaelico.', 'etimologia'),
  (498, 'citazione', 'Una birra al giorno toglie il medico di torno… forse. Ma di sicuro porta gli amici a casa.', 'variazione sul tema'),
  (499, 'citazione', 'Dove si fa la birra, si fa comunità.', 'motto degli homebrewer'),
  (500, 'citazione', 'Ad ogni cotta il suo brindisi, ad ogni brindisi la sua storia.', 'motto di BrewPastore');
